-- Move video file references from Google Drive IDs to private-bucket paths (wecore video project, bucket 'videos').
-- Rollback: update public."Videos" v set file_id=b.old_value from public.video_migration_backup b where b.tbl='Videos' and b.row_id=v.id::text; (same for the other tables)
create table if not exists public.video_migration_backup (tbl text not null, row_id text not null, col text not null, old_value text, primary key (tbl,row_id,col));
alter table public.video_migration_backup enable row level security;
insert into public.video_migration_backup select 'Videos', id::text, 'file_id', file_id from public."Videos" on conflict do nothing;
insert into public.video_migration_backup select 'Curces Soft', id::text, 'file_id', file_id from public."Curces Soft" on conflict do nothing;
insert into public.video_migration_backup select 'offer', id::text, 'file_id', file_id from public."offer" on conflict do nothing;
insert into public.video_migration_backup select 'training_videos', id::text, 'url', url from public.training_videos on conflict do nothing;
