update public."Curces Soft" t set file_id=x.p from (values (6,'Soft/Curces Soft 1.mp4'),(7,'Soft/Curces Soft 2.mp4'),(8,'Soft/Curces Soft 3.mp4'),(9,'Soft/Curces Soft 4.mp4')) as x(id,p) where x.id=t.id;
